local frequentSpellDescriptions = {
    [5254] = { en = "Transforms the enemy into a sheep for $d.", description = "Trasforma il nemico in una pecora per $d." },
    [5262] = { en = "Causes the caster to inflict an additional $5263s1 Fire damage to an enemy when the caster is using melee attacks. Lasts $d.", description = "Quando l'incantatore attacca in mischia, infligge al nemico $5263s1 danni da fuoco aggiuntivi. Dura $d." },
    [5280] = { en = "Causes thorns to sprout from the caster, inflicting $s1 Nature damage to melee attackers. The thorns last $d.", description = "Fa spuntare spine dall'incantatore, infliggendo $s1 danni da natura agli attaccanti in mischia. Le spine durano $d." },
    [5306] = { en = "Test", description = "Prova" },
    [5353] = { en = "Increases your damage with Two-Handed Maces by $s1 and gives a 2% chance of stunning the target for 8 seconds.", description = "Aumenta di $s1 i danni inflitti con le mazze a due mani e conferisce una probabilità del 2% di stordire il bersaglio per 8 secondi." },
    [5394] = { en = "Summons a Healing Stream Totem with $s1 health at the feet of the caster for $d that heals group members within $5672a1 yards for $5672s1 every $5672t1 seconds.", description = "Evoca ai piedi dell'incantatore un Totem del Flusso Vitale con $s1 salute per $d. Cura i membri del gruppo entro $5672a1 metri di $5672s1 ogni $5672t1 secondi." },
    [5424] = { en = "Immobilizes an enemy and inflicts $o1 damage over $d.", description = "Immobilizza un nemico e gli infligge $o1 danni nell'arco di $d." },
    [5453] = { en = "Increases your damage with One-Handed Swords by $s1 and your chance to parry by 5%.", description = "Aumenta di $s1 i danni inflitti con le spade a una mano e del 5% la probabilità di parare." },
    [5481] = { en = "Increases your chance to get a critical with One-Handed Swords by $s1.", description = "Aumenta di $s1 la probabilità di infliggere un colpo critico con le spade a una mano." },
    [5487] = { en = "Shapeshift into a bear, increasing melee attack power by $1178s4, armor contribution from items by $1178s1%, and health by $1178s2.  Also protects the caster from Polymorph effects and allows the use of various bear abilities.\r\n\r\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.", description = "Assumi forma d'orso, aumentando la potenza d'attacco in mischia di $1178s4, il contributo all'armatura degli oggetti del $1178s1% e la salute di $1178s2. Protegge inoltre l'incantatore dagli effetti di metamorfosi e permette di usare varie abilità da orso.\r\n\r\nLa mutazione libera l'incantatore dagli effetti di metamorfosi e da quelli che ostacolano il movimento." },
    [5504] = { en = "Conjures $s1 $lbottle:bottles; of water, providing the mage and $ghis:her; allies with something to drink.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Evoca $s1 $lbottiglia:bottiglie; d'acqua, offrendo al mago e ai $gsuoi:suoi; alleati qualcosa da bere.\r\n\r\nGli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti." },
    [5522] = { en = "Increases your damage with One-Handed Axes by 3.", description = "Aumenta di 3 i danni inflitti con le asce a una mano." },
    [5573] = { en = "You are protected from all physical attacks and spells for $d, but during that time you cannot attack or use physical abilities yourself.  Applies Forbearance for $25771d. Cannot be cast while Forbearance is active.", description = "Ti protegge da tutti gli attacchi fisici e dagli incantesimi per $d, ma durante questo periodo non puoi attaccare né usare abilità fisiche. Applica l'effetto Forbearance per $25771d. Non può essere lanciato mentre l'effetto è attivo." },
    [5581] = { en = "Applies a test script to the caster.  Exciting!", description = "Applica uno script di prova all'incantatore. Entusiasmante!" },
    [5675] = { en = "Summons a Mana Spring Totem with $s1 health at the feet of the caster for $d that restores $5677s1 mana every $5677t1 seconds to group members within $5677a1 yards.", description = "Evoca ai piedi dell'incantatore un Totem del Flusso di Mana con $s1 salute per $d. Ripristina $5677s1 mana ogni $5677t1 secondi ai membri del gruppo entro $5677a1 metri." },
    [5699] = { en = "Creates a Healthstone that can be used to instantly restore $5720s1 health.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra della Salute, utilizzabile per ripristinare istantaneamente $5720s1 salute.\r\n\r\nGli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti." },
    [5727] = { en = "Stuns the target for $d seconds.", description = "Stordisce il bersaglio per $d secondi." },
    [5730] = { en = "Summons a Stoneclaw Totem with $s1 health at the feet of the caster for $d that taunts creatures within $5729a1 yards to attack it.", description = "Evoca ai piedi dell'incantatore un Totem dell'Artiglio di Pietra con $s1 salute per $d. Provoca le creature entro $5729a1 metri, costringendole ad attaccarlo." },
    [5740] = { en = "Calls down a fiery rain to burn enemies in the area of effect for ${4*$1282380m1} Fire damage over $d.", description = "Fa piovere fuoco sui nemici nell'area, infliggendo ${4*$1282380m1} danni da fuoco nell'arco di $d." },
    [5761] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy, increasing their casting time by $5760s1% for $5760d.  $m2 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, aumentando del $5760s1% il suo tempo di lancio per $5760d. $m2 cariche." },
    [5763] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $5761h% chance of poisoning the enemy, increasing their casting time by $5760s1% for $5760d.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m2/60} minuti.\r\nOgni colpo ha una probabilità del $5761h% di avvelenare il nemico, aumentando del $5760s1% il suo tempo di lancio per $5760d. $m3 cariche." },
    [5794] = { en = "Increases your chance to block with a Shield (not a Buckler) by 6% and reflects $s2% of hostile spells back at the caster.", description = "Aumenta del 6% la probabilità di bloccare con uno scudo (non un brocchiere) e riflette sull'incantatore il $s2% degli incantesimi ostili." },
    [5795] = { en = "Increases your chance to block with a Shield (not a Buckler) by 7% and reflects $s2% of hostile spells back at the caster.", description = "Aumenta del 7% la probabilità di bloccare con uno scudo (non un brocchiere) e riflette sull'incantatore il $s2% degli incantesimi ostili." },
    [5796] = { en = "Increases your chance to block with a Shield (not a Buckler) by 8% and reflects $s2% of hostile spells back at the caster.", description = "Aumenta dell'8% la probabilità di bloccare con uno scudo (non un brocchiere) e riflette sull'incantatore il $s2% degli incantesimi ostili." },
    [5917] = { en = "Decreases target's chance to hit with attacks by $s1% for $d1.", description = "Riduce del $s1% la probabilità che il bersaglio colpisca con gli attacchi per $d1." },
    [5923] = { en = "Increases the critical strike chance of your Holy Shock and Holy Strike spells by $m2%, and all other spells by $m1%.", description = "Aumenta del $m2% la probabilità di colpo critico degli incantesimi Folgore Sacra e Assalto Sacro e del $m1% quella di tutti gli altri incantesimi." },
    [5934] = { en = "Increases your chance to parry by an additional $s2% for each combo point.  Lasts $d.", description = "Aumenta di un ulteriore $s2% la probabilità di parare per ogni punto combo. Dura $d." },
    [5979] = { en = "Increases your damage with Crossbows by $s1 and have a 2% chance of bleeding the target for 180 damage over 10 seconds.", description = "Aumenta di $s1 i danni inflitti con le balestre e conferisce una probabilità del 2% di far sanguinare il bersaglio, infliggendo 180 danni in 10 secondi." },
    [5998] = { en = "Allows a hunter to teach $ghis:her; tamed bird the Pester ability. Pester greatly increases the attack speed of the bird at the cost of dealing less damage. Every successful attack while in this mode renders the target unable to cast spells for a short time.\r\nRequires: \r\nPet Level 36+", description = "Permette al cacciatore di insegnare l'abilità Seccatura al $gsuo:suo; famiglio volatile addomesticato. Seccatura aumenta notevolmente la velocità d'attacco dell'uccello, riducendone però i danni. Ogni attacco riuscito in questa modalità impedisce per breve tempo al bersaglio di lanciare incantesimi.\r\nRequisiti: \r\nFamiglio di livello 36+" },
    [6017] = { en = "Allows a hunter to teach $ghis:her; tamed horse the Rapid Gallop ability. Rapid Gallop increases the movement speed of your horse.\r\nRequires: \r\nPet Level 13+", description = "Permette al cacciatore di insegnare Galoppo Rapido al $gsuo:suo; cavallo addomesticato, aumentandone la velocità di movimento.\r\nRequisiti: \r\nFamiglio di livello 13+" },
    [6027] = { en = "Allows a hunter to teach $ghis:her; tamed Spider the Web ability. Web renders an enemy unable to move.\r\nRequires: \r\nPet Level 30+", description = "Permette al cacciatore di insegnare Ragnatela al $gsuo:suo; ragno addomesticato. Ragnatela immobilizza un nemico.\r\nRequisiti: \r\nFamiglio di livello 30+" },
    [6028] = { en = "Allows a hunter to teach $ghis:her; tamed Spider the Web ability. Web renders an enemy unable to move.\r\nRequires: \r\nPet Level 37+", description = "Permette al cacciatore di insegnare Ragnatela al $gsuo:suo; ragno addomesticato. Ragnatela immobilizza un nemico.\r\nRequisiti: \r\nFamiglio di livello 37+" },
    [6037] = { en = "Allows a hunter to teach $ghis:her; tamed turtle the Thick Skin ability. Thick Skin gives your turtle a chance to increase it's armor value when hit.\r\nRequires: \r\nPet Level 32+", description = "Permette al cacciatore di insegnare Pelle Spessa alla $gsua:sua; tartaruga addomesticata. Quando viene colpita, la tartaruga ha una probabilità di aumentare la propria armatura.\r\nRequisiti: \r\nFamiglio di livello 32+" },
    [6141] = { en = "Ice shards pelt the target area doing ${$1279977m1*$d*$<frostdamage>} Frost damage over $d.", description = "Schegge di ghiaccio investono l'area bersaglio, infliggendo ${$1279977m1*$d*$<frostdamage>} danni da gelo nell'arco di $d." },
    [6197] = { en = "Zooms in the hunter's vision.  Only usable outdoors.  Lasts $d.", description = "Ingrandisce il campo visivo del cacciatore. Utilizzabile solo all'aperto. Dura $d." },
    [6219] = { en = "Calls down a fiery rain to burn enemies in the area of effect for ${4*$1282383m1} Fire damage over $d.", description = "Fa piovere fuoco sui nemici nell'area, infliggendo ${4*$1282383m1} danni da fuoco nell'arco di $d." },
    [6251] = { en = "Summons a Scarlet Cannon that fires at targets, dealing $17501s1 Holy damage. This effect deals $s2 times as much damage to Undead enemies.", description = "Evoca uno Scarlet Cannon che spara ai bersagli, infliggendo $17501s1 danni sacri. Infligge danni moltiplicati per $s2 ai Non Morti." },
    [6363] = { en = "Summons a Searing Totem with $s1 health at your feet for $d that repeatedly attacks an enemy within $6350r yards for $6350s1 Fire damage.", description = "Evoca ai tuoi piedi un Totem delle Fiamme con $s1 salute per $d. Attacca ripetutamente un nemico entro $6350r metri, infliggendo $6350s1 danni da fuoco." },
    [6364] = { en = "Summons a Searing Totem with $s1 health at your feet for $d that repeatedly attacks an enemy within $6351r yards for $6351s1 Fire damage.", description = "Evoca ai tuoi piedi un Totem delle Fiamme con $s1 salute per $d. Attacca ripetutamente un nemico entro $6351r metri, infliggendo $6351s1 danni da fuoco." },
    [6365] = { en = "Summons a Searing Totem with $s1 health at your feet for $d that repeatedly attacks an enemy within $6352r yards for $6352s1 Fire damage.", description = "Evoca ai tuoi piedi un Totem delle Fiamme con $s1 salute per $d. Attacca ripetutamente un nemico entro $6352r metri, infliggendo $6352s1 danni da fuoco." },
    [6366] = { en = "Creates a Lesser Firestone which can be used to enchant your weapon with Fire, increasing your spell critical strike chance by $23480s2% and the damage done by your Fire spells by up to $23480s1.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra di Fuoco Inferiore, utilizzabile per incantare l'arma con il fuoco, aumentando del $23480s2% la probabilità di colpo critico degli incantesimi e fino a $23480s1 i danni degli incantesimi di fuoco.\r\n\r\nGli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti." },
    [6375] = { en = "Summons a Healing Stream Totem with $s1 health at the feet of the caster for $d that heals group members within $6371a1 yards for $6371s1 every $6371t1 seconds.", description = "Evoca ai piedi dell'incantatore un Totem del Flusso Vitale con $s1 salute per $d. Cura i membri del gruppo entro $6371a1 metri di $6371s1 ogni $6371t1 secondi." },
    [6377] = { en = "Summons a Healing Stream Totem with $s1 health at the feet of the caster for $d that heals group members within $6372a1 yards for $6372s1 every $6372t1 seconds.", description = "Evoca ai piedi dell'incantatore un Totem del Flusso Vitale con $s1 salute per $d. Cura i membri del gruppo entro $6372a1 metri di $6372s1 ogni $6372t1 secondi." },
    [6390] = { en = "Summons a Stoneclaw Totem with $s1 health at the feet of the caster for $d that taunts creatures within $6393a1 yards to attack it.", description = "Evoca ai piedi dell'incantatore un Totem dell'Artiglio di Pietra con $s1 salute per $d. Provoca le creature entro $6393a1 metri, costringendole ad attaccarlo." },
    [6391] = { en = "Summons a Stoneclaw Totem with $s1 health at the feet of the caster for $d that taunts creatures within $6394a1 yards to attack it.", description = "Evoca ai piedi dell'incantatore un Totem dell'Artiglio di Pietra con $s1 salute per $d. Provoca le creature entro $6394a1 metri, costringendole ad attaccarlo." },
    [6392] = { en = "Summons a Stoneclaw Totem with $s1 health at the feet of the caster for $d that taunts creatures within $6395a1 yards to attack it.", description = "Evoca ai piedi dell'incantatore un Totem dell'Artiglio di Pietra con $s1 salute per $d. Provoca le creature entro $6395a1 metri, costringendole ad attaccarlo." },
    [6441] = { en = "Makes $s1 explosive shells.", description = "Crea $s1 proiettili esplosivi." },
    [6476] = { en = "Permanently enchant a cloak to give $13523s1 Shadow Resistance.", description = "Incanta permanentemente un mantello per conferire $13523s1 resistenza all'ombra." },
    [6495] = { en = "Summons an immobile Sentry Totem with $s1 health at your feet for $d that allows vision of nearby area and warns of enemies that attack it. Right-Click on buff to switch back and forth between totem sight and shaman sight.", description = "Evoca ai tuoi piedi un Totem Sentinella immobile con $s1 salute per $d, che permette di vedere l'area circostante e avvisa dei nemici che lo attaccano. Clic destro sul beneficio per alternare la visuale del totem a quella dello sciamano." },
    [6512] = { en = "Grants detect lesser invisibility for $d.", description = "Conferisce la capacità di individuare l'invisibilità inferiore per $d." },
    [6554] = { en = "Pummel the target for $s1 damage.  It also interrupts spellcasting and prevents any spell in that school from being cast for $d.", description = "Colpisce il bersaglio per $s1 danni. Interrompe inoltre il lancio degli incantesimi e impedisce di lanciare incantesimi di quella scuola per $d." },
    [6560] = { en = "Deal $s1 Fire damage to the target.", description = "Infligge $s1 danni da fuoco al bersaglio." },
    [6615] = { en = "Makes you immune to Stun and Movement Impairing effects for the next $d.   Does not remove effects already on the imbiber.", description = "Ti rende immune agli effetti di stordimento e a quelli che ostacolano il movimento per i prossimi $d. Non rimuove gli effetti già presenti su chi beve." },
    [6647] = { en = "A fast acting poison that does $s1 damage to the target.", description = "Un veleno ad azione rapida che infligge $s1 danni al bersaglio." },
    [6685] = { en = "Shoots at an enemy, inflicting normal damage and reducing the enemy's armor by $s2 for $d.", description = "Spara a un nemico, infliggendo danni normali e riducendone l'armatura di $s2 per $d." },
    [6774] = { en = "Finishing move that increases melee attack speed by $s2%.  Lasts longer per combo point:\r\n   1 point  : ${9*$<mult>} seconds\r\n   2 points: ${12*$<mult>} seconds\r\n   3 points: ${15*$<mult>} seconds\r\n   4 points: ${18*$<mult>} seconds\r\n   5 points: ${21*$<mult>} seconds", description = "Mossa finale che aumenta del $s2% la velocità d'attacco in mischia. La durata aumenta in base ai punti combo:\r\n   1 punto  : ${9*$<mult>} secondi\r\n   2 punti: ${12*$<mult>} secondi\r\n   3 punti: ${15*$<mult>} secondi\r\n   4 punti: ${18*$<mult>} secondi\r\n   5 punti: ${21*$<mult>} secondi" },
    [6785] = { en = "Ravage the target, causing $s2% damage plus 147 to the target.  Must be prowling and behind the target.  Awards $s3 combo $lpoint:points;.", description = "Devasta il bersaglio, infliggendo danni pari al $s2% più 147. Devi essere in agguato e alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
    [6787] = { en = "Ravage the target, causing $s2% damage plus 217 to the target.  Must be prowling and behind the target.  Awards $s3 combo $lpoint:points;.", description = "Devasta il bersaglio, infliggendo danni pari al $s2% più 217. Devi essere in agguato e alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
    [6800] = { en = "Shred the target, causing $s2% damage plus 72 to the target.  Must be behind the target.  Awards $s3 combo $lpoint:points;.", description = "Sventra il bersaglio, infliggendo danni pari al $s2% più 72. Devi trovarti alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
    [6873] = { en = "Increases the Frost damage taken by an enemy by $s1 for $d.", description = "Aumenta di $s1 i danni da gelo subiti da un nemico per $d." },
    [6949] = { en = "Launches a bolt of ice at an enemy, inflicting $s1 Frost damage.", description = "Scaglia una scheggia di ghiaccio contro un nemico, infliggendo $s1 danni da gelo." },
    [7054] = { en = "Curses an enemy for $d., periodically reducing one of its skills by $7038s1.", description = "Maledice un nemico per $d, riducendo periodicamente una delle sue abilità di $7038s1." },
    [7098] = { en = "Curses an enemy for $d., giving it $h% chance to heal its target by $7099s1 on attack.", description = "Maledice un nemico per $d, conferendogli una probabilità del $h% di curare il bersaglio di $7099s1 a ogni attacco." },
    [7125] = { en = "Inflicts $s1 Nature damage to an enemy every $t1 sec. Also drains $s2 mana every $t2 sec., transferring it to the caster. Lasts $d.", description = "Infligge $s1 danni da natura a un nemico ogni $t1 secondi. Sottrae inoltre $s2 mana ogni $t2 secondi e lo trasferisce all'incantatore. Dura $d." },
    [7137] = { en = "Charge an enemy, increasing speed and causing an additional $s2 damage on the first attack.", description = "Carica un nemico, aumentando la velocità e infliggendo $s2 danni aggiuntivi al primo attacco." },
    [7139] = { en = "Inflicts normal damage plus $s1 to nearby enemies, stunning them for $d. and increasing the Physical damage they take by $s3.", description = "Infligge ai nemici vicini i danni normali più $s1, li stordisce per $d. e aumenta di $s3 i danni fisici subiti." },
    [7154] = { en = "Uses dark magic to heal an ally for $s1.", description = "Usa la magia oscura per curare un alleato di $s1." },
    [7160] = { en = "Attempts to finish off a wounded enemy, inflicting normal damage plus $s1. Execute can only be used on enemies that have 20% or less health.", description = "Tenta di finire un nemico ferito, infliggendo i danni normali più $s1. Esecuzione può essere usata solo contro nemici con il 20% o meno di salute." },
    [7164] = { en = "Assumes a defensive stance that generates rage when the warrior is hit, as well as reducing rage decay while the warrior is out of combat. Lasts $d.", description = "Assumi una postura difensiva che genera rabbia quando il guerriero viene colpito e riduce la perdita di rabbia fuori dal combattimento. Dura $d." },
    [7288] = { en = "Burns the enemy for $s1 damage and then an additional $o1 damage over $d.", description = "Brucia il nemico, infliggendo $s1 danni e altri $o1 danni nell'arco di $d." },
    [7290] = { en = "Drains $o1 health over $d. from an enemy and its nearest ally, healing the caster for up to twice the amount of health stolen.", description = "Sottrae $o1 salute in $d a un nemico e al suo alleato più vicino, curando l'incantatore fino al doppio della salute sottratta." },
    [7331] = { en = "Heals the Paladin and nearby group members for $s1 every tick.", description = "Cura il paladino e i membri del gruppo vicini di $s1 a ogni intervallo." },
    [7381] = { en = "Increases crit chance by $s1%. Increases all damage taken by $s2%.", description = "Aumenta la probabilità di colpo critico del $s1%. Aumenta tutti i danni subiti del $s2%." },
    [7443] = { en = "Permanently enchant a piece of chest armor so that it increases the Intellect of the wearer by $7442s1.", description = "Incanta permanentemente un pezzo di armatura da torso per aumentare di $7442s1 l'Intelletto di chi lo indossa." },
    [7655] = { en = "Curses an enemy, reducing the Physical damage it deals by $8320s1 and decreasing its magical damage by $8320s2 for $8320d. Also, the curse increases the Physical damage the caster deals by $7657s1 and enhances its magical damage by $7657s2 for $7657d.", description = "Maledice un nemico, riducendo di $8320s1 i danni fisici inflitti e di $8320s2 quelli magici per $8320d. La maledizione aumenta inoltre di $7657s1 i danni fisici inflitti dall'incantatore e di $7657s2 quelli magici per $7657d." },
    [7721] = { en = "Adds 4 Fire damage to your weapon attack.", description = "Aggiunge 4 danni da fuoco all'attacco con l'arma." },
    [7843] = { en = "Increases Fire Spell Damage by $s1 for $d.", description = "Aumenta di $s1 i danni degli incantesimi di fuoco per $d." },
    [7901] = { en = "Reduces an enemy's Agility by $s1 for $d.", description = "Riduce l'Agilità di un nemico di $s1 per $d." },
    [7935] = { en = "Creates $M1 Vials of Strong Anti-Venom.", description = "Crea $M1 fiale di Strong Anti-Venom." },
    [8016] = { en = "Reduces an enemy's Spirit by $s1 for $d.", description = "Riduce lo Spirito di un nemico di $s1 per $d." },
    [8017] = { en = "Imbue the Shaman's weapon, increasing melee attack power by $10400s1 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.", description = "Imbeve l'arma dello sciamano, aumentando di $10400s1 la potenza d'attacco in mischia e permettendo agli attacchi in mischia con quell'arma di generare minaccia aggiuntiva. Dura 60 minuti." },
    [8018] = { en = "Imbue the Shaman's weapon, increasing melee attack power by $15567s1 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.", description = "Imbeve l'arma dello sciamano, aumentando di $15567s1 la potenza d'attacco in mischia e permettendo agli attacchi in mischia con quell'arma di generare minaccia aggiuntiva. Dura 60 minuti." },
    [8019] = { en = "Imbue the Shaman's weapon, increasing melee attack power by $15568s1 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.", description = "Imbeve l'arma dello sciamano, aumentando di $15568s1 la potenza d'attacco in mischia e permettendo agli attacchi in mischia con quell'arma di generare minaccia aggiuntiva. Dura 60 minuti." },
    [8024] = { en = "Imbue the Shaman's weapon with fire. Each hit causes ${$8026m1/77-1} to ${$8026m1/25} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. When applied to main hand, disables any benefit you personally receive from Flametongue Totem. Lasts for 60 minutes.", description = "Imbeve d'elemento igneo l'arma dello sciamano. Ogni colpo infligge da ${$8026m1/77-1} a ${$8026m1/25} danni da fuoco aggiuntivi, in base alla velocità dell'arma. Le armi più lente infliggono più danni da fuoco per colpo. Se applicato alla mano primaria, annulla qualsiasi beneficio personale ottenuto dal Totem della Lingua di Fuoco. Dura 60 minuti." },
    [8027] = { en = "Imbue the Shaman's weapon with fire. Each hit causes ${$8028m1/77-1} to ${$8028m1/25} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. When applied to main hand, disables any benefit you personally receive from Flametongue Totem. Lasts for 60 minutes.", description = "Imbeve d'elemento igneo l'arma dello sciamano. Ogni colpo infligge da ${$8028m1/77-1} a ${$8028m1/25} danni da fuoco aggiuntivi, in base alla velocità dell'arma. Le armi più lente infliggono più danni da fuoco per colpo. Se applicato alla mano primaria, annulla qualsiasi beneficio personale ottenuto dal Totem della Lingua di Fuoco. Dura 60 minuti." },
    [8030] = { en = "Imbue the Shaman's weapon with fire. Each hit causes ${$8029m1/77-1} to ${$8029m1/25} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. When applied to main hand, disables any benefit you personally receive from Flametongue Totem. Lasts for 60 minutes.", description = "Imbeve d'elemento igneo l'arma dello sciamano. Ogni colpo infligge da ${$8029m1/77-1} a ${$8029m1/25} danni da fuoco aggiuntivi, in base alla velocità dell'arma. Le armi più lente infliggono più danni da fuoco per colpo. Se applicato alla mano primaria, annulla qualsiasi beneficio personale ottenuto dal Totem della Lingua di Fuoco. Dura 60 minuti." },
    [8033] = { en = "Imbue the Shaman's weapon with frost.  Each hit has a chance of causing $8034s2 additional Frost damage and slowing the target's movement speed by $8034s1% for $8034d.  Lasts for 60 minutes.", description = "Imbeve di gelo l'arma dello sciamano. Ogni colpo ha una probabilità di infliggere $8034s2 danni da gelo aggiuntivi e ridurre del $8034s1% la velocità di movimento del bersaglio per $8034d. Dura 60 minuti." },
    [8038] = { en = "Imbue the Shaman's weapon with frost.  Each hit has a chance of causing $8037s2 additional Frost damage and slowing the target's movement speed by $8037s1% for $8037d.  Lasts for 60 minutes.", description = "Imbeve di gelo l'arma dello sciamano. Ogni colpo ha una probabilità di infliggere $8037s2 danni da gelo aggiuntivi e ridurre del $8037s1% la velocità di movimento del bersaglio per $8037d. Dura 60 minuti." },
    [8071] = { en = "Summons a Stoneskin Totem with $s1 health at the feet of the caster.  The totem protects party members within $8072a1 yards, reducing Physical damage taken by $8072s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem della Pelle di Pietra con $s1 salute. Protegge i membri del gruppo entro $8072a1 metri, riducendo di $8072s1 i danni fisici subiti. Dura $d." },
    [8075] = { en = "Summons a Strength of Earth Totem with $s1 health at the feet of the caster.  The totem increases the strength of party members within $8076a1 yards by $8076s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem della Forza della Terra con $s1 salute. Il totem aumenta la Forza dei membri del gruppo entro $8076a1 metri di $8076s1. Dura $d." },
    [8134] = { en = "The caster is surrounded by $n balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $26369s1 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts $d.", description = "L'incantatore è circondato da $n sfere di fulmini. Quando viene colpito da un incantesimo o da un attacco in mischia o a distanza, l'attaccante subisce $26369s1 danni da natura. La sfera si consuma all'impatto. Può attivarsi una sola sfera ogni pochi secondi. Dura $d." },
    [8139] = { en = "Reduces an enemy's Intellect by $s1 and its Spirit by $s2 for $d.", description = "Riduce l'Intelletto di un nemico di $s1 e il suo Spirito di $s2 per $d." },
    [8154] = { en = "Summons a Stoneskin Totem with $s1 health at the feet of the caster.  The totem protects party members within $8156a1 yards, reducing Physical damage taken by $8156s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Pelle di Pietra con $s1 salute. Protegge i membri del gruppo entro $8156a1 metri, riducendo di $8156s1 i danni fisici subiti. Dura $d." },
    [8155] = { en = "Summons a Stoneskin Totem with $s1 health at the feet of the caster.  The totem protects party members within $8157a1 yards, reducing Physical damage taken by $8157s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Pelle di Pietra con $s1 salute. Protegge i membri del gruppo entro $8157a1 metri, riducendo di $8157s1 i danni fisici subiti. Dura $d." },
    [8160] = { en = "Summons a Strength of Earth Totem with $s1 health at the feet of the caster.  The totem increases the strength of party members within $8162a1 yards by $8162s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem della Forza della Terra con $s1 salute. Il totem aumenta la Forza dei membri del gruppo entro $8162a1 metri di $8162s1. Dura $d." },
    [8161] = { en = "Summons a Strength of Earth Totem with $s1 health at the feet of the caster.  The totem increases the strength of party members within $8163a1 yards by $8163s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem della Forza della Terra con $s1 salute. Il totem aumenta la Forza dei membri del gruppo entro $8163a1 metri di $8163s1. Dura $d." },
    [8166] = { en = "Summons a Poison Cleansing Totem with $s1 health at the feet of the caster that attempts to remove 1 poison effect from party members within $8168a1 yards every $8167t1 seconds.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Purificazione Veleno con $s1 salute, che tenta di rimuovere un effetto di veleno dai membri del gruppo entro $8168a1 metri ogni $8167t1 secondi. Dura $d." },
    [8170] = { en = "Summons a Disease Cleansing Totem with $s1 health at the feet of the caster that attempts to remove 1 disease effect from party members within $8171a1 yards every $8172t1 seconds.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Purificazione Malattie con $s1 salute, che tenta di rimuovere un effetto di malattia dai membri del gruppo entro $8171a1 metri ogni $8172t1 secondi. Dura $d." },
    [8177] = { en = "Summons a Grounding Totem with $s1 health at the feet of the caster that will redirect one harmful spell cast on a nearby party member to itself every $8179t1 seconds.  Will not redirect area of effect spells.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Radicamento con $s1 salute. Ogni $8179t1 secondi devia su di sé un incantesimo nocivo lanciato contro un membro del gruppo vicino. Non devia gli incantesimi ad area. Dura $d." },
    [8181] = { en = "Summons a Frost Resistance Totem with $s1 health at the feet of the caster for $d.  The totem increases party and raid members' frost resistance by $8182s1, if within $8182a1 yards.", description = "Evoca ai piedi dell'incantatore un Totem Resistenza al Gelo con $s1 salute per $d. Aumenta di $8182s1 la resistenza al gelo dei membri del gruppo e dell'incursione entro $8182a1 metri." },
    [8184] = { en = "Summons a Fire Resistance Totem with $s1 health at the feet of the caster for $d that increases the fire resistance of party and raid members within $8185a1 yards by $8185s1.", description = "Evoca ai piedi dell'incantatore un Totem Resistenza al Fuoco con $s1 salute per $d. Il totem aumenta la resistenza al fuoco dei membri del gruppo e dell'incursione entro $8185a1 metri di $8185s1." },
    [8212] = { en = "Your size is increased and your Strength goes up by $s1 to match your new size.  Lasts $d.", description = "Aumenta la tua taglia e la Forza di $s1 per adattarla alla nuova taglia. Dura $d." },
    [8227] = { en = "Summons a Flametongue Totem with $s1 health at the feet of the caster. The totem enchants all party members' main-hand weapons with fire if they are within $8230a1 yards. Each hit causes ${$8253m1/77*$<mult>-1} to ${$8253M1/25*$<mult>} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem della Lingua di Fuoco con $s1 salute. Incanta con il fuoco le armi nella mano primaria dei membri del gruppo entro $8230a1 metri. Ogni colpo infligge da ${$8253m1/77*$<mult>-1} a ${$8253M1/25*$<mult>} danni da fuoco aggiuntivi in base alla velocità dell'arma. Le armi più lente infliggono più danni da fuoco per colpo. Dura $d." },
    [8232] = { en = "Imbue the Shaman's weapon with wind.  Each hit has a 20% chance of granting you $8233s2 extra $lattack:attacks; with $8233s1 extra melee attack power. When applied to main hand, disables any benefit you personally receive from Windfury Totem. Lasts for 60 minutes.", description = "Imbeve di vento l'arma dello sciamano. Ogni colpo ha una probabilità del 20% di concederti $8233s2 $lattacco:attacchi; aggiuntivi con $8233s1 potenza d'attacco in mischia aggiuntiva. Se applicato alla mano primaria, annulla qualsiasi beneficio personale ottenuto dal Totem della Furia del Vento. Dura 60 minuti." },
    [8235] = { en = "Imbue the Shaman's weapon with wind.  Each hit has a 20% chance of granting you $8236s2 extra $lattack:attacks; with $8236s1 extra melee attack power. When appied to main hand, disables any benefit you personally receive from Windfury Totem. Lasts for 60 minutes.", description = "Imbeve di vento l'arma dello sciamano. Ogni colpo ha una probabilità del 20% di concederti $8236s2 $lattacco:attacchi; aggiuntivi con $8236s1 potenza d'attacco in mischia aggiuntiva. Se applicato alla mano primaria, annulla qualsiasi beneficio personale ottenuto dal Totem della Furia del Vento. Dura 60 minuti." },
    [8249] = { en = "Summons a Flametongue Totem with $s1 health at the feet of the caster. The totem enhances the melee attacks of all party members within $8250a1 yards. Each main hand hit causes  ${$8248m1/77*$<mult>-1} to ${$8248M1/25*$<mult>} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem della Lingua di Fuoco con $s1 salute. Potenzia gli attacchi in mischia dei membri del gruppo entro $8250a1 metri. Ogni colpo della mano primaria infligge da ${$8248m1/77*$<mult>-1} a ${$8248M1/25*$<mult>} danni da fuoco aggiuntivi in base alla velocità dell'arma. Le armi più lente infliggono più danni da fuoco per colpo. Dura $d." },
    [8331] = { en = "The dynamite for Non-Engineers that nearly always gets to the target! Inflicts $s1 Fire damage in a 5 yard radius.", description = "La dinamite per chi non è ingegnere che quasi sempre colpisce il bersaglio! Infligge $s1 danni da fuoco entro un raggio di 5 metri." },
    [8375] = { en = "Permanently enchant gloves to grant +$13838s1 mining skill.", description = "Incanta permanentemente i guanti per conferire +$13838s1 abilità di estrazione mineraria." },
    [8397] = { en = "$s1% chance when struck in melee to gain a holy shield, absorbing $10368s1 damage for $10368d. This chance is doubled in Wasteland and Haunted areas.", description = "Probabilità del $s1% quando vieni colpito in mischia di ottenere uno scudo sacro che assorbe $10368s1 danni per $10368d. La probabilità raddoppia nelle aree Wasteland e Haunted." },
    [8416] = { en = "Launches Arcane Missiles at the enemy, causing $8419s1 Arcane damage each second for $d.", description = "Scaglia Missili Arcani contro il nemico, infliggendo $8419s1 danni arcani ogni secondo per $d." },
    [8417] = { en = "Launches Arcane Missiles at the enemy, causing $8418s1 Arcane damage each second for $d.", description = "Scaglia Missili Arcani contro il nemico, infliggendo $8418s1 danni arcani ogni secondo per $d." },
    [8422] = { en = "Calls down a pillar of fire, burning all enemies within the area for $s1 Fire damage and an additional ${$1279987m1*4} Fire damage over $d. Only one Flamestrike can be active per Mage at a time.", description = "Fa cadere una colonna di fuoco che brucia i nemici nell'area, infliggendo $s1 danni da fuoco e altri ${$1279987m1*4} danni da fuoco nell'arco di $d. Ogni mago può avere una sola Colonna di Fuoco attiva alla volta." },
    [8423] = { en = "Calls down a pillar of fire, burning all enemies within the area for $s1 Fire damage and an additional ${$1279988m1*4} Fire damage over $d. Only one Flamestrike can be active per Mage at a time.", description = "Fa cadere una colonna di fuoco che brucia i nemici nell'area, infliggendo $s1 danni da fuoco e altri ${$1279988m1*4} danni da fuoco nell'arco di $d. Ogni mago può avere una sola Colonna di Fuoco attiva alla volta." },
    [8427] = { en = "Ice shards pelt the target area doing ${$1279978m1*$d*$<frostdamage>} Frost damage over $d.", description = "Schegge di ghiaccio investono l'area bersaglio, infliggendo ${$1279978m1*$d*$<frostdamage>} danni da gelo nell'arco di $d." },
    [8512] = { en = "Summons a Windfury Totem with $s1 health at the feet of the caster. The totem enhances the melee attacks of all party members within $8515a1 yards.  Each main hand hit has a 20% chance of granting the attacker $8516s2 extra attack with ${$8516m1*$<mult>} extra melee attack power. Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem della Furia del Vento con $s1 salute. Potenzia gli attacchi in mischia dei membri del gruppo entro $8515a1 metri. Ogni colpo della mano primaria ha una probabilità del 20% di conferire all'attaccante $8516s2 attacchi aggiuntivi con ${$8516m1*$<mult>} potenza d'attacco in mischia aggiuntiva. Dura $d." },
    [8627] = { en = "Backstab the target, causing $s2% of weapon damage plus an additional $s1 to the target.  Must be stealthed and behind the target.  Awards $s3 combo point.", description = "Pugnala il bersaglio alle spalle, infliggendo il $s2% dei danni dell'arma più $s1 danni aggiuntivi. Devi essere furtivo e trovarti alle spalle del bersaglio. Conferisce $s3 punti combo." },
    [8679] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy which instantly inflicts $8680s1 Nature damage.  $m2 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo istantaneamente $8680s1 danni da natura. $m2 cariche." },
    [8686] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy which instantly inflicts $8685s1 Nature damage.  $m2 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo istantaneamente $8685s1 danni da natura. $m2 cariche." },
    [8687] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $8686h% chance of poisoning the enemy which instantly inflicts $8685s1 Nature damage.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m2/60} minuti.\r\nOgni colpo ha una probabilità del $8686h% di avvelenare il nemico, infliggendo istantaneamente $8685s1 danni da natura. $m3 cariche." },
    [8688] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy which instantly inflicts $8689s1 Nature damage.  $m2 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo istantaneamente $8689s1 danni da natura. $m2 cariche." },
    [8691] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $8688h% chance of poisoning the enemy which instantly inflicts $8689s1 Nature damage.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m2/60} minuti.\r\nOgni colpo ha una probabilità del $8688h% di avvelenare il nemico, infliggendo istantaneamente $8689s1 danni da natura. $m3 cariche." },
    [8693] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy, increasing their casting time by $8692s1% for $8692d.  $m2 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, aumentando il tempo di lancio del nemico del $8692s1% per $8692d. $m2 cariche." },
    [8694] = { en = "Coats a weapon with poison that lasts for ${$m2/60} minutes.\r\nEach strike has a $8693h% chance of poisoning the enemy, increasing their casting time by $8692s1% for $8692d.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m2/60} minuti.\r\nOgni colpo ha una probabilità del $8693h% di avvelenare il nemico, aumentando il suo tempo di lancio del $8692s1% per $8692d. $m3 cariche." },
    [8716] = { en = "Stuns an enemy and reduces its movement speed by $s2%, in addition to increasing the caster's melee damage by $s1. Lasts $d.", description = "Stordisce un nemico e ne riduce la velocità di movimento del $s2%, aumentando inoltre di $s1 i danni in mischia dell'incantatore. Dura $d." },
    [8835] = { en = "Summons a Grace of Air Totem with $s1 health at the feet of the caster.  The totem increases the agility of party members within $8836a1 yards by $8836s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Grazia dell'Aria con $s1 salute. Il totem aumenta l'Agilità dei membri del gruppo entro $8836a1 metri di $8836s1. Dura $d." },
    [8874] = { en = "Allows the rogue to sneak around, but reduces your speed to $s2% of normal.  Lasts until cancelled.", description = "Permette al furfante di muoversi furtivamente, ma riduce la velocità al $s2% del normale. Dura finché non viene annullato." },
    [8909] = { en = "Increases the caster's armor and resistance to spells for $d.", description = "Aumenta l'armatura dell'incantatore e la resistenza agli incantesimi per $d." },
    [8992] = { en = "Shred the target, causing $s2% damage plus 99 to the target.  Must be behind the target.  Awards $s3 combo $lpoint:points;.", description = "Sventra il bersaglio, infliggendo danni pari al $s2% più 99. Devi trovarti alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
    [9005] = { en = "Pounce, stunning the target for $d and causing $9007o1 damage over $9007d.  Must be prowling and behind the target.  Awards $s3 combo $lpoint:points;.", description = "Balza sul bersaglio, stordendolo per $d e infliggendo $9007o1 danni nell'arco di $9007d. Devi essere in agguato e alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
    [9159] = { en = "Puts the enemy target to sleep for up to $d.  Any damage caused will awaken the target.  ", description = "Addormenta il bersaglio nemico per un massimo di $d. Qualsiasi danno lo risveglia.  " },
    [9173] = { en = "Cast an AOE spell", description = "Lancia un incantesimo ad area." },
    [9452] = { en = "Gives your damaging melee attacks a chance to reduce the target's Attack Power by ${$m1/-3*$440667m1}, and increase your Attack Power by $m1% for $440667d.", description = "I tuoi attacchi in mischia offensivi hanno una probabilità di ridurre la potenza d'attacco del bersaglio di ${$m1/-3*$440667m1} e di aumentare la tua potenza d'attacco del $m1% per $440667d." },
    [9453] = { en = "Reduces the duration of  Fear and Disorient effects on you by $s1%.", description = "Riduce del $s1% la durata degli effetti di paura e disorientamento che subisci." },
    [9512] = { en = "Instantly restores $s1 energy.", description = "Ripristina istantaneamente $s1 energia." },
    [9632] = { en = "Attack all nearby enemies, dealing weapon damage plus $9633s1 every $t1 sec for $d, and reducing your own movement speed by $s2%.", description = "Attacca tutti i nemici vicini, infliggendo i danni dell'arma più $9633s1 ogni $t1 secondi per $d e riducendo del $s2% la tua velocità di movimento." },
    [9634] = { en = "Shapeshift into a dire bear, increasing melee attack power by $9635s4, armor contribution from items by $9635s1%, and health by $9635s3.  Also protects the caster from Polymorph effects and allows the use of various bear abilities.\r\n\r\nThe act of shapeshifting frees the caster of Polymorph and Movement Impairing effects.", description = "Assumi la forma Dire Bear, aumentando la potenza d'attacco in mischia di $9635s4, il contributo all'armatura degli oggetti del $9635s1% e la salute di $9635s3. Protegge inoltre l'incantatore dagli effetti di metamorfosi e permette di usare varie abilità da orso.\r\n\r\nLa mutazione libera l'incantatore dagli effetti di metamorfosi e da quelli che ostacolano il movimento." },
    [9733] = { en = "In a whirlwind of steel you attack all nearby enemies for $d, causing weapon damage plus an additional $3231s1 every $t1 seconds.", description = "In un turbine d'acciaio, attacchi tutti i nemici vicini per $d, infliggendo i danni dell'arma più $3231s1 danni aggiuntivi ogni $t1 secondi." },
    [9799] = { en = "All critical strikes against you cause $s1% of the damage taken to the attacker as well. The damage caused by Eye for an Eye will not exceed 50% of the Paladin's total health.", description = "Tutti i colpi critici contro di te infliggono all'attaccante anche il $s1% dei danni subiti. I danni di Occhio per Occhio non superano il 50% della salute totale del paladino." },
    [9829] = { en = "Shred the target, causing $s2% damage plus 144 to the target.  Must be behind the target.  Awards $s3 combo $lpoint:points;.", description = "Sventra il bersaglio, infliggendo danni pari al $s2% più 144. Devi trovarti alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
    [9830] = { en = "Shred the target, causing $s2% damage plus 180 to the target.  Must be behind the target.  Awards $s3 combo $lpoint:points;.", description = "Sventra il bersaglio, infliggendo danni pari al $s2% più 180. Devi trovarti alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
    [9866] = { en = "Ravage the target, causing $s2% damage plus 273 to the target.  Must be prowling and behind the target.  Awards $s3 combo $lpoint:points;.", description = "Devasta il bersaglio, infliggendo danni pari al $s2% più 273. Devi essere in agguato e alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
    [9867] = { en = "Ravage the target, causing $s2% damage plus 343 to the target.  Must be prowling and behind the target.  Awards $s3 combo $lpoint:points;.", description = "Devasta il bersaglio, infliggendo danni pari al $s2% più 343. Devi essere in agguato e alle sue spalle. Conferisce $s3 $lpunto:punti; combo." },
    [10053] = { en = "Conjures a mana citrine that can be used to instantly restore $10057s1 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Evoca una citrina di mana, utilizzabile per ripristinare istantaneamente $10057s1 mana.\r\n\r\nGli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti." },
    [10054] = { en = "Conjures a mana ruby that can be used to instantly restore $10058s1 mana.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Evoca un rubino di mana, utilizzabile per ripristinare istantaneamente $10058s1 mana.\r\n\r\nGli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti." },
    [10060] = { en = "Infuses the target with power, increasing their spell damage and healing done by $s2% for $d.", description = "Infondi il bersaglio di potere, aumentando del $s2% i danni degli incantesimi e le cure effettuate per $d." },
    [10185] = { en = "Ice shards pelt the target area doing ${$1279979m1*$d*$<frostdamage>} Frost damage over $d.", description = "Schegge di ghiaccio investono l'area bersaglio, infliggendo ${$1279979m1*$d*$<frostdamage>} danni da gelo nell'arco di $d." },
    [10186] = { en = "Ice shards pelt the target area doing ${$1279980m1*$d*$<frostdamage>} Frost damage over $d.", description = "Schegge di ghiaccio investono l'area bersaglio, infliggendo ${$1279980m1*$d*$<frostdamage>} danni da gelo nell'arco di $d." },
    [10187] = { en = "Ice shards pelt the target area doing ${$1279949m1*$d*$<frostdamage>} Frost damage over $d.", description = "Schegge di ghiaccio investono l'area bersaglio, infliggendo ${$1279949m1*$d*$<frostdamage>} danni da gelo nell'arco di $d." },
    [10211] = { en = "Launches Arcane Missiles at the enemy, causing $10273s1 Arcane damage each second for $d.", description = "Scaglia Missili Arcani contro il nemico, infliggendo $10273s1 danni arcani ogni secondo per $d." },
    [10212] = { en = "Launches Arcane Missiles at the enemy, causing $10274s1 Arcane damage each second for $d.", description = "Scaglia Missili Arcani contro il nemico, infliggendo $10274s1 danni arcani ogni secondo per $d." },
    [10215] = { en = "Calls down a pillar of fire, burning all enemies within the area for $s1 Fire damage and an additional ${$1279989m1*4} Fire damage over $d. Only one Flamestrike can be active per Mage at a time.", description = "Fa cadere una colonna di fuoco che brucia i nemici nell'area, infliggendo $s1 danni da fuoco e altri ${$1279989m1*4} danni da fuoco nell'arco di $d. Ogni mago può avere una sola Flamestrike attiva alla volta." },
    [10216] = { en = "Calls down a pillar of fire, burning all enemies within the area for $s1 Fire damage and an additional ${$1279990m1*4} Fire damage over $d. Only one Flamestrike can be active per Mage at a time.", description = "Fa cadere una colonna di fuoco che brucia i nemici nell'area, infliggendo $s1 danni da fuoco e altri ${$1279990m1*4} danni da fuoco nell'arco di $d. Ogni mago può avere una sola Flamestrike attiva alla volta." },
    [10236] = { en = "Shows the location of all nearby humanoids on the minimap for $d.", description = "Mostra sulla minimappa la posizione di tutti gli umanoidi vicini per $d." },
    [10241] = { en = "Shows the location of all nearby dragonkin on the minimap for $d.", description = "Mostra sulla minimappa la posizione di tutti i dragoni vicini per $d." },
    [10351] = { en = "Defense +$s1 for $d1.", description = "Difesa +$s1 per $d1." },
    [10370] = { en = "Leave lacerations on the target, increasing physical damage taken by $s1 for $d. Stacks up to $u times.", description = "Lacera il bersaglio, aumentando di $s1 i danni fisici subiti per $d. Si accumula fino a $u volte." },
    [10399] = { en = "Imbue the Shaman's weapon, increasing melee attack power by $15569s1 and allowing melee attacks to cause additional threat when using that weapon.  Lasts for 60 minutes.", description = "Imbeve l'arma dello sciamano, aumentando di $15569s1 la potenza d'attacco in mischia e permettendo agli attacchi in mischia con quell'arma di generare minaccia aggiuntiva. Dura 60 minuti." },
    [10406] = { en = "Summons a Stoneskin Totem with $s1 health at the feet of the caster.  The totem protects party members within $10403a1 yards, reducing Physical damage taken by $10403s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Pelle di Pietra con $s1 salute. Protegge i membri del gruppo entro $10403a1 metri, riducendo di $10403s1 i danni fisici subiti. Dura $d." },
    [10407] = { en = "Summons a Stoneskin Totem with $s1 health at the feet of the caster.  The totem protects party members within $10404a1 yards, reducing Physical damage taken by $10404s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Pelle di Pietra con $s1 salute. Protegge i membri del gruppo entro $10404a1 metri, riducendo di $10404s1 i danni fisici subiti. Dura $d." },
    [10408] = { en = "Summons a Stoneskin Totem with $s1 health at the feet of the caster.  The totem protects party members within $10405a1 yards, reducing Physical damage taken by $10405s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Pelle di Pietra con $s1 salute. Protegge i membri del gruppo entro $10405a1 metri, riducendo di $10405s1 i danni fisici subiti. Dura $d." },
    [10427] = { en = "Summons a Stoneclaw Totem with $s1 health at the feet of the caster for $d that taunts creatures within $10423a1 yards to attack it.", description = "Evoca ai piedi dell'incantatore un Totem Artiglio di Pietra con $s1 salute per $d. Provoca le creature entro $10423a1 metri, costringendole ad attaccarlo." },
    [10428] = { en = "Summons a Stoneclaw Totem with $s1 health at the feet of the caster for $d that taunts creatures within $10424a1 yards to attack it.", description = "Evoca ai piedi dell'incantatore un Totem Artiglio di Pietra con $s1 salute per $d. Provoca le creature entro $10424a1 metri, costringendole ad attaccarlo." },
    [10431] = { en = "The caster is surrounded by $n balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $26370s1 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts $d.", description = "L'incantatore è circondato da $n sfere di fulmini. Quando viene colpito da un incantesimo o da un attacco in mischia o a distanza, l'attaccante subisce $26370s1 danni da natura. La sfera si consuma all'impatto. Può attivarsi una sola sfera ogni pochi secondi. Dura $d." },
    [10432] = { en = "The caster is surrounded by $n balls of lightning.  When a spell, melee or ranged attack hits the caster, the attacker will be struck for $26363s1 Nature damage.  This expends one lightning ball.  Only one ball will fire every few seconds.  Lasts $d.", description = "L'incantatore è circondato da $n sfere di fulmini. Quando viene colpito da un incantesimo o da un attacco in mischia o a distanza, l'attaccante subisce $26363s1 danni da natura. La sfera si consuma all'impatto. Può attivarsi una sola sfera ogni pochi secondi. Dura $d." },
    [10437] = { en = "Summons a Searing Totem with $s1 health at your feet for $d that repeatedly attacks an enemy within $10435r yards for $10435s1 Fire damage.", description = "Evoca ai tuoi piedi un Totem Fiammeggiante con $s1 salute per $d. Attacca ripetutamente un nemico entro $10435r metri, infliggendo $10435s1 danni da fuoco." },
    [10438] = { en = "Summons a Searing Totem with $s1 health at your feet for $d that repeatedly attacks an enemy within $10436r yards for $10436s1 Fire damage.", description = "Evoca ai tuoi piedi un Totem Fiammeggiante con $s1 salute per $d. Attacca ripetutamente un nemico entro $10436r metri, infliggendo $10436s1 danni da fuoco." },
    [10442] = { en = "Summons a Strength of Earth Totem with $s1 health at the feet of the caster.  The totem increases the strength of party members within $10441a1 yards by $10441s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Forza della Terra con $s1 salute. Il totem aumenta la Forza dei membri del gruppo entro $10441a1 metri di $10441s1. Dura $d." },
    [10456] = { en = "Imbue the Shaman's weapon with frost.  Each hit has a chance of causing $10458s2 additional Frost damage and slowing the target's movement speed by $10458s1% for $10458d.  Lasts for 60 minutes.", description = "Imbeve di gelo l'arma dello sciamano. Ogni colpo ha una probabilità di infliggere $10458s2 danni da gelo aggiuntivi e ridurre del $10458s1% la velocità di movimento del bersaglio per $10458d. Dura 60 minuti." },
    [10462] = { en = "Summons a Healing Stream Totem with $s1 health at the feet of the caster for $d that heals group members within $10460a1 yards for $10460s1 every $10460t1 seconds.", description = "Evoca ai piedi dell'incantatore un Totem del Flusso Curativo con $s1 salute per $d. Cura i membri del gruppo entro $10460a1 metri di $10460s1 ogni $10460t1 secondi." },
    [10463] = { en = "Summons a Healing Stream Totem with $s1 health at the feet of the caster for $d that heals group members within $10461a1 yards for $10461s1 every $10461t1 seconds.", description = "Evoca ai piedi dell'incantatore un Totem del Flusso Curativo con $s1 salute per $d. Cura i membri del gruppo entro $10461a1 metri di $10461s1 ogni $10461t1 secondi." },
    [10478] = { en = "Summons a Frost Resistance Totem with $s1 health at the feet of the caster for $d.  The totem increases party and raid members' frost resistance by $10476s1, if within $10476a1 yards.", description = "Evoca ai piedi dell'incantatore un Totem Resistenza al Gelo con $s1 salute per $d. Aumenta di $10476s1 la resistenza al gelo dei membri del gruppo e dell'incursione entro $10476a1 metri." },
    [10479] = { en = "Summons a Frost Resistance Totem with $s1 health at the feet of the caster for $d.  The totem increases party and raid members' frost resistance by $10477s1, if within $10477a1 yards.", description = "Evoca ai piedi dell'incantatore un Totem Resistenza al Gelo con $s1 salute per $d. Aumenta di $10477s1 la resistenza al gelo dei membri del gruppo e dell'incursione entro $10477a1 metri." },
    [10486] = { en = "Imbue the Shaman's weapon with wind.  Each hit has a 20% chance of granting you $10484s2 extra $lattack:attacks; with $10484s1 extra melee attack power. When applied to main hand, disables any benefit you personally receive from Windfury Totem. Lasts for 60 minutes.", description = "Imbeve di vento l'arma dello sciamano. Ogni colpo ha una probabilità del 20% di concederti $10484s2 $lattacco:attacchi; aggiuntivi con $10484s1 potenza d'attacco in mischia aggiuntiva. Se applicato alla mano primaria, annulla qualsiasi beneficio personale ottenuto dal Totem Furia del Vento. Dura 60 minuti." },
    [10495] = { en = "Summons a Mana Spring Totem with $s1 health at the feet of the caster for $d that restores $10491s1 mana every $10491t1 seconds to group members within $10491a1 yards.", description = "Evoca ai piedi dell'incantatore un Totem della Fonte di Mana con $s1 salute per $d. Ripristina $10491s1 mana ogni $10491t1 secondi ai membri del gruppo entro $10491a1 metri." },
    [10496] = { en = "Summons a Mana Spring Totem with $s1 health at the feet of the caster for $d that restores $10493s1 mana every $10493t1 seconds to group members within $10493a1 yards.", description = "Evoca ai piedi dell'incantatore un Totem della Fonte di Mana con $s1 salute per $d. Ripristina $10493s1 mana ogni $10493t1 secondi ai membri del gruppo entro $10493a1 metri." },
    [10497] = { en = "Summons a Mana Spring Totem with $s1 health at the feet of the caster for $d that restores $10494s1 mana every $10494t1 seconds to group members within $10494a1 yards.", description = "Evoca ai piedi dell'incantatore un Totem della Fonte di Mana con $s1 salute per $d. Ripristina $10494s1 mana ogni $10494t1 secondi ai membri del gruppo entro $10494a1 metri." },
    [10526] = { en = "Summons a Flametongue Totem with $s1 health at the feet of the caster. The totem enhances the melee attacks of all party members within $10521a1 yards. Each main hand hit causes  ${$10523m1/77*$<mult>-1} to ${$10523M1/25*$<mult>} additional Fire damage, based on the speed of the weapon. Slower weapons cause more fire damage per swing. Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Lingua di Fuoco con $s1 salute. Potenzia gli attacchi in mischia dei membri del gruppo entro $10521a1 metri. Ogni colpo della mano primaria infligge da ${$10523m1/77*$<mult>-1} a ${$10523M1/25*$<mult>} danni da fuoco aggiuntivi in base alla velocità dell'arma. Le armi più lente infliggono più danni da fuoco per colpo. Dura $d." },
    [10537] = { en = "Summons a Fire Resistance Totem with $s1 health at the feet of the caster for $d that increases the fire resistance of party and raid members within $10534a1 yards by $10534s1.", description = "Evoca ai piedi dell'incantatore un Totem Resistenza al Fuoco con $s1 salute per $d. Il totem aumenta la resistenza al fuoco dei membri del gruppo e dell'incursione entro $10534a1 metri di $10534s1." },
    [10538] = { en = "Summons a Fire Resistance Totem with $s1 health at the feet of the caster for $d that increases the fire resistance of party and raid members within $10535a1 yards by $10535s1.", description = "Evoca ai piedi dell'incantatore un Totem Resistenza al Fuoco con $s1 salute per $d. Il totem aumenta la resistenza al fuoco dei membri del gruppo e dell'incursione entro $10535a1 metri di $10535s1." },
    [10585] = { en = "Summons a Magma Totem with $s1 health at the feet of the caster for $d that causes $10579s1 Fire damage to creatures within $10579a1 yards every $10582t1 seconds.", description = "Evoca ai piedi dell'incantatore un Totem di Magma con $s1 salute per $d. Infligge $10579s1 danni da fuoco alle creature entro $10579a1 metri ogni $10582t1 secondi." },
    [10586] = { en = "Summons a Magma Totem with $s1 health at the feet of the caster for $d that causes $10580s1 Fire damage to creatures within $10580a1 yards every $10583t1 seconds.", description = "Evoca ai piedi dell'incantatore un Totem di Magma con $s1 salute per $d. Infligge $10580s1 danni da fuoco alle creature entro $10580a1 metri ogni $10583t1 secondi." },
    [10587] = { en = "Summons a Magma Totem with $s1 health at the feet of the caster for $d that causes $10581s1 Fire damage to creatures within $10581a1 yards every $10584t1 seconds.", description = "Evoca ai piedi dell'incantatore un Totem di Magma con $s1 salute per $d. Infligge $10581s1 danni da fuoco alle creature entro $10581a1 metri ogni $10584t1 secondi." },
    [10595] = { en = "Summons a Nature Resistance Totem with $s1 health at the feet of the caster for $d that increases the nature resistance of party and raid members within $10596a1 yards by $10596s1.", description = "Evoca ai piedi dell'incantatore un Totem Resistenza alla Natura con $s1 salute per $d. Il totem aumenta la resistenza alla natura dei membri del gruppo e dell'incursione entro $10596a1 metri di $10596s1." },
    [10600] = { en = "Summons a Nature Resistance Totem with $s1 health at the feet of the caster for $d that increases the nature resistance of party and raid members within $10598a1 yards by $10598s1.", description = "Evoca ai piedi dell'incantatore un Totem Resistenza alla Natura con $s1 salute per $d. Il totem aumenta la resistenza alla natura dei membri del gruppo e dell'incursione entro $10598a1 metri di $10598s1." },
    [10601] = { en = "Summons a Nature Resistance Totem with $s1 health at the feet of the caster for $d that increases the nature resistance of party and raid members within $10599a1 yards by $10599s1.", description = "Evoca ai piedi dell'incantatore un Totem Resistenza alla Natura con $s1 salute per $d. Il totem aumenta la resistenza alla natura dei membri del gruppo e dell'incursione entro $10599a1 metri di $10599s1." },
    [10613] = { en = "Summons a Windfury Totem with $s1 health at the feet of the caster. The totem enhances the melee attacks of all party members within $10609a1 yards. Each main hand hit has a 20% chance of granting the attacker $10608s2 extra attack with ${$10608m1*$<mult>} extra melee attack power. Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Furia del Vento con $s1 salute. Potenzia gli attacchi in mischia dei membri del gruppo entro $10609a1 metri. Ogni colpo della mano primaria ha una probabilità del 20% di conferire all'attaccante $10608s2 attacchi aggiuntivi con ${$10608m1*$<mult>} potenza d'attacco in mischia aggiuntiva. Dura $d." },
    [10614] = { en = "Summons a Windfury Totem with $s1 health at the feet of the caster. The totem enhances the melee attacks of all party members within $10612a1 yards. Each main hand hit has a 20% chance of granting the attacker $10610s2 extra attack with ${$10610m1*$<mult>} extra melee attack power. Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Furia del Vento con $s1 salute. Potenzia gli attacchi in mischia dei membri del gruppo entro $10612a1 metri. Ogni colpo della mano primaria ha una probabilità del 20% di conferire all'attaccante $10610s2 attacchi aggiuntivi con ${$10610m1*$<mult>} potenza d'attacco in mischia aggiuntiva. Dura $d." },
    [10627] = { en = "Summons a Grace of Air Totem with $s1 health at the feet of the caster.  The totem increases the agility of party members within $10626a1 yards by $10626s1.  Lasts $d.", description = "Evoca ai piedi dell'incantatore un Totem Grazia dell'Aria con $s1 salute. Il totem aumenta l'Agilità dei membri del gruppo entro $10626a1 metri di $10626s1. Dura $d." },
    [10654] = { en = "Test Spell - For Debugging", description = "Incantesimo di prova - Debug" },
    [10887] = { en = "Pummels nearby enemies for normal damage plus $s1 and interrupts any spell being cast 75% of the time for $d.", description = "Colpisce i nemici vicini, infliggendo i danni normali più $s1 e interrompendo gli incantesimi in corso con probabilità del 75% per $d." },
    [10967] = { en = "Reduces nearby enemies' armor by $s1% for $d.", description = "Riduce del $s1% l'armatura dei nemici vicini per $d." },
    [11016] = { en = "Drains $s1 health and $s2 mana from an enemy, transferring them to the caster.", description = "Sottrae a un nemico $s1 salute e $s2 mana e li trasferisce all'incantatore." },
    [11071] = { en = "Gives your Chill effects a $s1% chance to Freeze the target for $12494d.", description = "Gli effetti di Freddo hanno una probabilità del $s1% di congelare il bersaglio per $12494d." },
    [11078] = { en = "Reduces the cooldown of your Fire Blast spell by ${$s1/-1000} sec. Killing a non-trivial target increases the critical strike chance of your next Fire Blast cast within $1312934d by $m2%.", description = "Riduce di ${$s1/-1000} secondi il tempo di recupero di Detonazione di Fuoco. Uccidere un bersaglio impegnativo aumenta la probabilità di colpo critico del successivo lancio di Detonazione di Fuoco entro $1312934d del $m2%." },
    [11083] = { en = "Gives your Fire spells a $s1% chance to not lose casting time when you take damage and reduces the threat caused by your Fire spells by $s2%.", description = "Gli incantesimi di fuoco hanno una probabilità del $s1% di non perdere tempo di lancio quando subisci danni. Riduce inoltre del $s2% la minaccia generata dagli incantesimi di fuoco." },
    [11094] = { en = "Causes your Fire Ward to have a $s1% chance to reflect Fire spells while active.", description = "Mentre è attiva, Protezione dal Fuoco ha una probabilità del $s1% di riflettere gli incantesimi di fuoco." },
    [11095] = { en = "Your Scorch spell has a $m1% chance to cause your target to be vulnerable to Fire damage. This vulnerability increases all Fire damage you deal to your target by $22959s1% and lasts $22959d, stacking up to $22959u times.", description = "Bruciatura ha una probabilità del $m1% di rendere il bersaglio vulnerabile ai danni da fuoco. Questa vulnerabilità aumenta del $22959s1% tutti i danni da fuoco che gli infliggi e dura $22959d. Si accumula fino a $22959u volte." },
    [11100] = { en = "Increases the range of your Fire spells by $s1 yards.", description = "Aumenta di $s1 metri la portata degli incantesimi di fuoco." },
    [11103] = { en = "Gives your Fire spells a $m1% chance to stun the target for $12355d.", description = "Gli incantesimi di fuoco hanno una probabilità del $m1% di stordire il bersaglio per $12355d." },
    [11108] = { en = "Increases the critical strike chance of your Flamestrike spell by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico dell'incantesimo Colonna di Fuoco." },
    [11115] = { en = "Increases the critical strike chance of your Fire spells by $s1%.", description = "Aumenta del $s1% la probabilità di colpo critico degli incantesimi di fuoco." },
    [11119] = { en = "Your critical strikes from Fire damage spells cause the target to burn for an additional $m1% of your spell's damage over $412538d.", description = "I colpi critici degli incantesimi che infliggono danni da fuoco fanno bruciare il bersaglio, infliggendo altri danni pari al $m1% dei danni dell'incantesimo nell'arco di $412538d." },
    [11124] = { en = "Increases the damage done by your Fire spells by $s1%.", description = "Aumenta del $s1% i danni inflitti dagli incantesimi di fuoco." },
    [11129] = { en = "When activated, this spell causes each of your Fire damage spell hits to increase your critical strike chance with Fire damage spells by $28682s1%.  This effect lasts until you have caused $n non-periodic critical strikes with Fire spells.", description = "Quando attivato, ogni colpo dei tuoi incantesimi che infliggono danni da fuoco aumenta del $28682s1% la probabilità di colpo critico degli incantesimi di fuoco. L'effetto dura finché non infliggi $n colpi critici non periodici con incantesimi di fuoco." },
    [11151] = { en = "Increases the damage done by your Frost spells by $s1%.", description = "Aumenta del $s1% i danni inflitti dagli incantesimi di gelo." },
    [11160] = { en = "Reduces the mana cost of your Frost spells by $s1% and reduces the threat caused by your Frost spells by $s2%.", description = "Riduce del $s1% il costo in mana degli incantesimi di gelo e del $s2% la minaccia che generano." },
    [11170] = { en = "Increases the critical strike chance of all your spells against Frozen targets by $m1%.", description = "Aumenta del $m1% la probabilità di colpo critico di tutti i tuoi incantesimi contro i bersagli congelati." },
    [11175] = { en = "Increases the duration of your Chill effects by $s1% and reduces the target's speed by an additional $s2%.", description = "Aumenta del $s1% la durata degli effetti di Freddo e riduce la velocità del bersaglio di un ulteriore $s2%." },
    [11180] = { en = "Gives your Frost damage spells a $m2% chance to apply the Winter's Chill effect, which increases the chance your Ice Lance and Frostbolt spells will critically hit the target by $12579s1% for $12579d. Stacks up to $s1 times.", description = "Gli incantesimi che infliggono danni da gelo hanno una probabilità del $m2% di applicare l'effetto Brivido Invernale, che aumenta del $12579s1% la probabilità che Lancia di Ghiaccio e Dardo di Gelo infliggano un colpo critico al bersaglio per $12579d. Si accumula fino a $s1 volte." },
    [11185] = { en = "Adds a Chill effect to your Blizzard spell. This effect lowers the target's movement speed by $m1% for $12484d.", description = "Aggiunge un effetto di Freddo a Tormenta, riducendo del $m1% la velocità di movimento del bersaglio per $12484d." },
    [11189] = { en = "Increases the Armor and resistance given by your Frost Armor and Ice Armor spells by $s1%. In addition, gives your Frost Ward a $s2% chance to reflect Frost spells and effects while active.", description = "Aumenta del $s1% l'armatura e la resistenza conferite dagli incantesimi Armatura di Gelo e Armatura di Ghiaccio. Inoltre, Protezione dal Gelo ha una probabilità del $s2% di riflettere gli incantesimi e gli effetti di gelo quando è attiva." },
    [11190] = { en = "Increases the damage dealt by your Cone of Cold spell by $s1%.", description = "Aumenta del $s1% i danni inflitti da Cono di Freddo." },
    [11202] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy, slowing their movement speed by $11201s1% for $11201d.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, riducendone la velocità di movimento del $11201s1% per $11201d." },
    [11207] = { en = "Increases the critical strike damage bonus of your Frost spells by $s1%.", description = "Aumenta del $s1% il bonus ai danni da colpo critico degli incantesimi di gelo." },
    [11210] = { en = "Reduces your target's resistance to all your spells by $s2 and reduces the threat caused by your Arcane spells by $s1%.", description = "Riduce di $s2 la resistenza del bersaglio a tutti i tuoi incantesimi e del $s1% la minaccia generata dai tuoi incantesimi arcani." },
    [11222] = { en = "Improves your chance to hit with Arcane spells by $s1%.", description = "Aumenta del $s1% la probabilità di colpire con gli incantesimi arcani." },
    [11232] = { en = "Increases your Intellect by $m1% and increases the critical strike damage bonus of your Arcane spells by $m2%.", description = "Aumenta del $m1% il tuo Intelletto e del $m2% il bonus ai danni da colpo critico degli incantesimi arcani." },
    [11237] = { en = "Gives you a $m1% chance to avoid interruption caused by damage while channeling Arcane Missiles and a $m2% chance while casting Arcane Blast.", description = "Conferisce una probabilità del $m1% di evitare interruzioni causate dai danni durante il lancio di Missili Arcani e del $m2% durante il lancio di Detonazione Arcana." },
    [11242] = { en = "Increases the critical strike chance of your Arcane spells by $m1%.", description = "Aumenta del $m1% la probabilità di colpo critico degli incantesimi arcani." },
    [11247] = { en = "Increases the range of your Arcane spells by $m1 yards.", description = "Aumenta di $m1 metri la portata degli incantesimi arcani." },
    [11252] = { en = "Decreases the Mana lost per point of damage taken when your Mana Shield spell is active by $m1% and increases the resistances granted by your Mage Armor spell by $m2%.", description = "Riduce del $m1% il mana perso per ogni punto di danno subito mentre Scudo di Mana è attivo e aumenta del $m2% le resistenze conferite da Armatura Magica." },
    [11255] = { en = "Your Counterspell also Silences the target for ${$m1/1000} sec.", description = "Controincantesimo silenzia il bersaglio anche per ${$m1/1000} secondi." },
    [11338] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy which instantly inflicts $11335s1 Nature damage.  $m2 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo istantaneamente $11335s1 danni da natura. $m2 cariche." },
    [11339] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy which instantly inflicts $11336s1 Nature damage.  $m2 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo istantaneamente $11336s1 danni da natura. $m2 cariche." },
    [11340] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy which instantly inflicts $11337s1 Nature damage.  $m2 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo istantaneamente $11337s1 danni da natura. $m2 cariche." },
    [11350] = { en = "Does $11351s1 fire damage to any enemies within a $11351a1 yard radius around the caster every 3 seconds for $d", description = "Infligge $11351s1 danni da fuoco ai nemici entro $11351a1 metri dall'incantatore ogni 3 secondi per $d" },
    [11355] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy for $11353o1 Nature damage over $11353d.  Stacks up to $11353u times on a single target.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo $11353o1 danni da natura nell'arco di $11353d. Si accumula fino a $11353u volte sullo stesso bersaglio. $m3 cariche." },
    [11356] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy for $11354o1 Nature damage over $11354d.  Stacks up to $11354u times on a single target.  $m3 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, infliggendo $11354o1 danni da natura nell'arco di $11354d. Si accumula fino a $11354u volte sullo stesso bersaglio. $m3 cariche." },
    [11371] = { en = "Increases resistance to shadow by $s1.  If an enemy strikes the imbiber, the attacker has a 30% chance of being inflicted with disease that increases their damage taken by $11374s1 for $11374d.  Lasts for $d.", description = "Aumenta di $s1 la resistenza all'ombra. Quando il bersaglio viene colpito da un nemico, l'attaccante ha una probabilità del 30% di contrarre una malattia che aumenta i danni subiti di $11374s1 per $11374d. Dura $d." },
    [11374] = { en = "Increases physical damage taken by $s1 for $d", description = "Aumenta di $s1 i danni fisici subiti per $d" },
    [11397] = { en = "Inflicts normal damage plus $s1 to an enemy, reducing its Strength by $s2 and its Agility by $s3 for $d.", description = "Infligge a un nemico i danni normali più $s1, riducendone la Forza di $s2 e l'Agilità di $s3 per $d." },
    [11399] = { en = "Coats a weapon with poison that lasts for ${$m1/60} minutes.\r\nEach strike has a $h% chance of poisoning the enemy, increasing their casting time by $11398s1% for $11398d.  $m2 charges.", description = "Riveste un'arma di veleno per ${$m1/60} minuti.\r\nOgni colpo ha una probabilità del $h% di avvelenare il nemico, aumentando il suo tempo di lancio del $11398s1% per $11398d. $m2 cariche." },
    [11406] = { en = "Increases Attack Power by $s1 against Demons.  Lasts $d.", description = "Aumenta di $s1 la potenza d'attacco contro i demoni. Dura $d." },
    [11442] = { en = "Diseases an enemy, inflicting $s1 Shadow damage every $t1 sec. and draining $s2 mana every $t2 sec., transferring it to the caster. Lasts $d.", description = "Infetta un nemico, infliggendo $s1 danni da ombra ogni $t1 secondi e sottraendo $s2 mana ogni $t2 secondi, trasferendoli all'incantatore. Dura $d." },
    [11474] = { en = "Increases spell shadow damage by up to $s1 for $d.", description = "Aumenta fino a $s1 i danni degli incantesimi d'ombra per $d." },
    [11677] = { en = "Calls down a fiery rain to burn enemies in the area of effect for ${4*$1282384m1} Fire damage over $d.", description = "Fa piovere fuoco sui nemici nell'area, infliggendo ${4*$1282384m1} danni da fuoco nell'arco di $d." },
    [11678] = { en = "Calls down a fiery rain to burn enemies in the area of effect for ${4*$1282385m1} Fire damage over $d.", description = "Fa piovere fuoco sui nemici nell'area, infliggendo ${4*$1282385m1} danni da fuoco nell'arco di $d." },
    [11729] = { en = "Creates a Greater Healthstone that can be used to instantly restore $5723s1 health.\r\n\r\nConjured items disappear if logged out for more than 15 minutes.", description = "Crea una Pietra della Salute Superiore, utilizzabile per ripristinare istantaneamente $5723s1 salute.\r\n\r\nGli oggetti evocati scompaiono se rimani disconnesso per più di 15 minuti." },
    [11789] = { en = "Underwater Breath lasts $s1% longer than normal.", description = "La durata di Respirazione Subacquea aumenta del $s1% rispetto al normale." },
    [11826] = { en = "Channels a bolt of lightning and hurls it towards all enemies in front of the caster causing $11828s1 Nature damage. The caster is then surrounded by a barrier of electricity for $11841d.", description = "Canalizza un fulmine e lo scaglia contro tutti i nemici davanti all'incantatore, infliggendo $11828s1 danni da natura. L'incantatore viene poi circondato da una barriera elettrica per $11841d." },
    [11836] = { en = "Stuns an enemy and inflicts $s1 Frost damage every $t1 sec. for $d.", description = "Stordisce un nemico e gli infligge $s1 danni da gelo ogni $t1 secondi per $d." },
    [11923] = { en = "Reforge the sword with $s2 Steel Bars, $s3 Strong Flux, $s4 Elemental Fire and $s5 Heavy Grinding Stones.", description = "Riforgia la spada usando $s2 lingotti d'acciaio, $s3 Strong Flux, $s4 Elemental Fire e $s5 pietre da molatura pesanti." },
    [11958] = { en = "You become encased in a block of ice, protecting you from all physical attacks and spells for $d, but during that time you cannot attack, move, or cast spells.", description = "Ti avvolge in un blocco di ghiaccio che ti protegge da tutti gli attacchi fisici e dagli incantesimi per $d, ma durante questo periodo non puoi attaccare, muoverti o lanciare incantesimi." },
    [11972] = { en = "Bashes an enemy with the caster's shield, inflicting Physical damage and interrupting the spell being cast for $d.", description = "Colpisce un nemico con lo scudo dell'incantatore, infliggendo danni fisici e interrompendo l'incantesimo in corso per $d." },
    [12022] = { en = "Gives $M1 additional stamina to party members within $a1 yards.", description = "Conferisce $M1 Tempra aggiuntiva ai membri del gruppo entro $a1 metri." },
    [12042] = { en = "For the next $d, your spells deal $s1% more damage while costing $s2% more mana to cast.", description = "Per i prossimi $d, i tuoi incantesimi infliggono il $s1% di danni in più, ma costano il $s2% di mana in più." },
    [12166] = { en = "Cripples an enemy, inflicting normal damage plus $s1 and reducing its Strength by $s2 for $d.", description = "Azzoppa un nemico, infliggendo i danni normali più $s1 e riducendone la Forza di $s2 per $d." },
    [12257] = { en = "Deals $12278s1 Fire damage every $m1 sec for $d1 to all enemies in front of you. Deals $s2 times as much damage to Plants. Gets you quite drunk too!", description = "Infligge $12278s1 danni da fuoco ogni $m1 secondi a tutti i nemici davanti a te per $d1. Infligge danni moltiplicati per $s2 alle piante. Fa anche ubriacare parecchio!" },
    [12278] = { en = "Deals $s1 Fire every $12257t1 sec.", description = "Infligge $s1 danni da fuoco ogni $12257t1 secondi." },
    [12281] = { en = "Gives you a $m1% chance to get an extra attack on the same target after dealing damage with your Sword.", description = "Dopo aver inflitto danni con la spada, hai una probabilità del $m1% di ottenere un attacco aggiuntivo contro lo stesso bersaglio." },
    [12284] = { en = "Your attacks with Maces and Staves ignore $m1% of your target's armor.", description = "Gli attacchi con mazze e bastoni ignorano il $m1% dell'armatura del bersaglio." },
    [12286] = { en = "Increases the Bleed damage done by your Rend ability by $s1%.", description = "Aumenta del $s1% i danni da sanguinamento inflitti da Squartamento." },
    [12289] = { en = "Gives your Hamstring ability a $m1% chance to immobilize the target for $23694d.", description = "Azzoppamento ha una probabilità del $m1% di immobilizzare il bersaglio per $23694d." },
    [12292] = { en = "Your next $n melee attacks strike an additional nearby opponent.", description = "I tuoi prossimi $n attacchi in mischia colpiscono anche un altro avversario vicino." },
    [12295] = { en = "Tactical Mastery lets you retain up to an additional $s1 Rage when you change stances.", description = "Maestria Tattica ti permette di conservare fino a $s1 rabbia aggiuntiva quando cambi postura." },
    [12296] = { en = "Generates $m2 Rage every $m3 sec while in combat, and reduces Rage loss while out of combat by $s4%.", description = "Genera $m2 rabbia ogni $m3 secondi durante il combattimento e riduce del $s4% la perdita di rabbia fuori dal combattimento." },
    [12298] = { en = "Increases your chance to Block attacks with your shield by $s1% and grants you a $m2% chance to generate ${$1310318m1/10} Rage when you Block.", description = "Aumenta del $s1% la probabilità di bloccare gli attacchi con lo scudo e conferisce una probabilità del $m2% di generare ${$1310318m1/10} rabbia quando blocchi." },
    [12301] = { en = "Increases all the Rage generated by your Bloodrage ability by $m1%.", description = "Aumenta del $m1% tutta la rabbia generata da Rabbia Sanguinaria." },
    [12311] = { en = "Gives your Shield Bash ability a $m1% chance to Silence the target for $18498d.", description = "Colpo di Scudo ha una probabilità del $m1% di silenziare il bersaglio per $18498d." },
    [12312] = { en = "Reduces the cooldown of your Shield Wall ability by ${$m1/-60000}.1 min.", description = "Riduce di ${$m1/-60000}.1 minuti il tempo di recupero di Muro di Scudo." },
    [12317] = { en = "Gives you a $h% chance to deal $m1% increased Physical damage for $12880d after being the victim of any damaging attack.", description = "Dopo aver subito un attacco che infligge danni, hai una probabilità del $h% di infliggere il $m1% di danni fisici in più per $12880d." },
    [12321] = { en = "Increases the radius of your Battle Shout and Demoralizing Shout abilities by $s1%.", description = "Aumenta del $s1% il raggio di Grido di Battaglia e Grido Demoralizzante." },
    [12322] = { en = "Gives you a $m1% chance to generate ${$12964m1/10} additional Rage when you deal melee damage with a weapon. This effect is increased to ${($12964m1/10)*2} Rage for two-handed weapons.", description = "Quando infliggi danni in mischia con un'arma, hai una probabilità del $m1% di generare ${$12964m1/10} rabbia aggiuntiva. Con le armi a due mani l'effetto aumenta a ${($12964m1/10)*2} rabbia." },
    [12328] = { en = "When activated, increases your Physical damage done by $s1% and makes you immune to Fear effects, but increases all damage you take by $s3%. Lasts $d.", description = "Quando attivato, aumenta del $s1% i danni fisici inflitti e ti rende immune agli effetti di paura, ma aumenta del $s3% tutti i danni subiti. Dura $d." },
    [12329] = { en = "Reduces the Rage cost of your Cleave ability by ${$m1/-10}.", description = "Riduce di ${$m1/-10} il costo in rabbia di Fendente." },
    [12355] = { en = "Fire spells have a chance to stun the target for $12355d.", description = "Gli incantesimi di fuoco hanno una probabilità di stordire il bersaglio per $12355d." },
    [12544] = { en = "Encases the caster in a layer of frost that lasts $d. The thick ice increases armor by $s1, slows melee attackers' movement to $6136s2%, and increases the time between their attacks by $6136s1%.", description = "Avvolge l'incantatore in uno strato di gelo per $d. Il ghiaccio spesso aumenta l'armatura di $s1, riduce al $6136s2% la velocità di movimento degli attaccanti in mischia e aumenta del $6136s1% l'intervallo tra i loro attacchi." },
}

for id, description in pairs(frequentSpellDescriptions) do
    ns.data.spellDescriptionOverrides[id] = description
end
